service.method:

SELECT GRLN.HOUSE_CODE 
     , GRLN.COMPANY_CODE 
     , GRLN.GR_NUMBER 
     , GRLN.MATERIAL_NUMBER 
     , GRLN.DESCRIPTION_LOC 
     , GRLN.SELLER_CODE
     , GRLN.ADD_USER_ID
  FROM SGRLN GRLN WITH (NOLOCK)
 WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
       AND GR_NUMBER = ${GR_NUMBER} 
       AND PO_NUMBER = ${PO_NUMBER} 
       AND PO_SEQ    = ${PO_SEQ}


SELECT RQGL.HOUSE_CODE 
     , RQGL.COMPANY_CODE 
     , RQGL.RFQ_NUMBER 
     , RQGL.RFQ_COUNT 
     , RQGL.SUBJECT 
     , RQGL.REMARK 
     , RQGL.RFQ_CLOSE_DATE
     , RQGL.RFQ_CLOSE_TIME
	 , RQGL.PURCHASE_USER_ID
	 , RQGL.PURCHASE_USER_NAME
	 , RQGL.ATTACH_NO
	 , ( SELECT TOP 1 SELLER_NAME_LOC FROM SSUGL
	     WHERE HOUSE_CODE = ${session.HOUSE_CODE}
	 	 AND SELLER_CODE = ${session.COMPANY_CODE}
	 ) AS SELLER_NAME_LOC
  FROM SRQGL RQGL WITH (NOLOCK)
 WHERE RQGL.HOUSE_CODE = ${session.HOUSE_CODE} 
       AND RQGL.RFQ_NUMBER   = ${RFQ_NUMBER} 
       AND RQGL.RFQ_COUNT    = ${RFQ_COUNT}


SELECT SELLER_CODE 
  FROM SQTLN QTLN  WITH (NOLOCK)
 WHERE RFQ_NUMBER || RFQ_COUNT || RFQ_SEQ IN 
       (SELECT RFQ_NUMBER || RFQ_COUNT || RFQ_SEQ 
         FROM SDRLN  WITH (NOLOCK)
        WHERE EXEC_NUMBER = ${EXEC_NUMBER}  
              AND EXEC_COUNT = ${EXEC_COUNT} 
       ) 
       AND NVL(SETTLE_FLAG, 'N') = ${SETTLE_FLAG} 
 GROUP BY SELLER_CODE


SELECT TYPE 
     , DES_FILE_NAME 
     , SRC_FILE_NAME 
  FROM SFILE WITH (NOLOCK)
 WHERE HOUSE_CODE = ${session.HOUSE_CODE} 
       AND DOC_NO = ${ATTACH_NO}


	UPDATE SUSMT 
	   SET  PASSWORD  = ${PASSWORD}
	       ,PW_RESET_FLAG = 'Y'
           ,PW_RESET_DATE = ${current.DATE} 
	 WHERE NVL(DEL_FLAG, 'N' ) = 'N'
	   AND UPPER(USER_ID)  = UPPER(${USER_ID})
